def pill(state):
    colors = {"IDLE": MUTED, "SIGNING": TEAL, "PREDICTING": AMBER, "LOW CONFIDENCE": RED}
    return f"<span class='pill' style='background:{colors.get(state, MUTED)}'>{state}</span>"


def top5_html(probs):
    rows = []
    for i in np.argsort(-probs)[:5]:
        p = float(probs[i])
        rows.append(f"<div class='top5'><span class='n'>{GLOSS[i]}</span><span class='b'><div class='bar-wrap'>"
                    f"<div class='bar' style='width:{p*100:.0f}%'></div></div></span><span class='p mono'>{p*100:.1f}%</span></div>")
    return "".join(rows)


def pred_card(probs, hi_on, accepted=None, latency=None):
    if probs is None:
        return ("<div class='card'><div class='muted'>Prediction</div><div class='pred-word'>—</div>"
                "<div class='muted'>Perform a sign to see the translation.</div></div>")
    i = int(np.argmax(probs)); p = float(probs[i])
    word = "No sign detected" if i == REJ else GLOSS[i]
    hi = f"<div class='pred-hi'>{HINDI[i]}</div>" if hi_on and i != REJ else ""
    lat = f" · {latency:.0f} ms" if latency is not None else ""
    return (f"<div class='card'><div class='muted'>Prediction{lat}</div><div class='pred-word'>{word}</div>{hi}"
            f"<div class='bar-wrap' style='margin-top:10px'><div class='bar' style='width:{p*100:.0f}%;background:{TEAL if accepted else AMBER}'></div></div>"
            f"<div class='mono muted' style='margin-top:4px'>confidence {p*100:.1f}%</div></div>")


