def skeleton_canvas(seq252, caption=None, size=(480, 320)):
    """Draw one frame's hands relative to the face (landmark replay for the simulate mode / sample tab)."""
    import mediapipe as mp
    conn = list(mp.solutions.hands.HAND_CONNECTIONS)
    W, H = size
    im = Image.new("RGB", (W, H), PANEL); dr = ImageDraw.Draw(im)
    ox, oy, sc = W // 2, 60, 46.0
    dr.ellipse([ox - 38, oy - 64, ox + 38, oy + 70], outline="#3B475C", width=2)
    for e in (-23, 23):
        dr.ellipse([ox + e - 4, oy - 20, ox + e + 4, oy - 12], fill="#3B475C")
    pts = np.asarray(seq252, dtype=np.float32).reshape(4, 21, 3)
    for blk, col in ((2, TEAL), (3, ORANGE)):
        h = pts[blk]
        if np.abs(h).sum() == 0:
            continue
        xy = [(ox + p[0] * sc, oy + p[1] * sc) for p in h]
        for a, b in conn:
            dr.line([xy[a], xy[b]], fill=col, width=2)
        for p in xy:
            dr.ellipse([p[0] - 2.5, p[1] - 2.5, p[0] + 2.5, p[1] + 2.5], fill=col)
    if caption:
        dr.text((10, H - 22), caption, fill=TEXT)
    return np.asarray(im)


def _rgb(h):
    return tuple(int(h[i:i + 2], 16) for i in (1, 3, 5))


def draw_landmarks(rgb, res):
    import mediapipe as mp
    du, sol = mp.solutions.drawing_utils, mp.solutions.holistic
    MUTED_, TEAL_, ORANGE_ = _rgb(MUTED), _rgb(TEAL), _rgb(ORANGE)
    if res.pose_landmarks is not None:
        du.draw_landmarks(rgb, res.pose_landmarks, sol.POSE_CONNECTIONS, du.DrawingSpec(MUTED_, 1, 1), du.DrawingSpec(MUTED_, 1, 1))
    if res.left_hand_landmarks is not None:
        du.draw_landmarks(rgb, res.left_hand_landmarks, sol.HAND_CONNECTIONS, du.DrawingSpec(TEAL_, 2, 3), du.DrawingSpec(TEAL_, 2, 2))
    if res.right_hand_landmarks is not None:
        du.draw_landmarks(rgb, res.right_hand_landmarks, sol.HAND_CONNECTIONS, du.DrawingSpec(ORANGE_, 2, 3), du.DrawingSpec(ORANGE_, 2, 2))
    return rgb


