def do_speak(text, show=True):
    if not text.strip():
        return
    if speech_lang.startswith("Hindi"):
        hindi = " ".join(HINDI[GLOSS.index(w)] if w in GLOSS else w for w in text.split())
        mp3 = isl_core.hindi_mp3(hindi)
        if mp3:
            ss["audio"] = mp3
            return
        notice_ph.warning("Offline — falling back to English speech")
    isl_core.speak_english(text)


def cb_speak():
    ss["speak_now"] = True


def cb_undo():
    if ss["words"]:
        ss["words"].pop()


def cb_clear():
    ss["words"] = []; ss["pending"] = None


def cb_save():
    t = transcript_text()
    if t:
        sid = ensure_session("live", ENG_KEY[engine_label], DEV_LABEL)
        if sid:
            db("INSERT INTO transcripts (session_id, text, language, spoken) VALUES (%s,%s,%s,%s)",
               (sid, t, "hi" if speech_lang.startswith("Hindi") else "en", False))
            ss["notice"] = "Transcript saved"


def cb_choose(idx, probs):
    ss["words"].append(GLOSS[idx].lower())
    ss["pending"] = None
    ss["last_accepted"] = True
    log_prediction("live", probs, True, 0, 0, 0, ENG_KEY[engine_label], DEV_LABEL, corrected=True)


def classify(base_seq, n_frames, lm_ms, source="live"):
    t0 = time.perf_counter()
    probs = PRED.predict(base_seq)
    model_ms = (time.perf_counter() - t0) * 1000
    order = np.argsort(-probs)
    p1, p2 = float(probs[order[0]]), float(probs[order[1]])
    top = int(order[0])
    accepted = top != REJ and p1 >= thr and (p1 - p2) >= margin
    ss["last_probs"], ss["last_accepted"], ss["last_latency"] = probs, accepted, lm_ms + model_ms
    ss["event"] += 1
    if accepted:
        ss["words"].append(GLOSS[top].lower()); ss["pending"] = None; ss["status"] = "IDLE"
    else:
        ss["status"] = "LOW CONFIDENCE"
        ss["pending"] = [int(i) for i in order[:3] if int(i) != REJ] if top != REJ else None
    log_prediction(source, probs, accepted, n_frames, lm_ms, model_ms, ENG_KEY[engine_label], DEV_LABEL)
    return probs, accepted


